// CSD_RATIONALE_BEGIN
// Root cause of attempt 37 regression (20% → 3%):
//   The 45 SMILES guidance examples caused the model to anchor so strongly on
//   those specific templates that nearly all 100 independent runs copied from
//   the same 3 guidance molecules (~33 runs each). Guidance examples are
//   the PRIMARY degeneracy driver when there are too many specific templates.
//
// What made Attempt 9 the best (20%):
//   1. Only 10 guidance examples → moderate anchoring → 20 unique molecules.
//   2. NCO-ONLY check ("N=C=O", not "O=C=N"): the vast majority of isocyanate
//      SMILES are written "O=C=N..." format (O first). When hasNCO==0, we DON'T
//      close early → forced extension at T=1.6 → longer, more diverse outputs.
//   3. Phase-1 penalty on ["C","CC","O"] for first 6 tokens pushes model away
//      from the most common token choices.
//
// Changes for this attempt:
//   A) Remove ALL specific SMILES examples from guidance. With 0 examples, the
//      model cannot copy; it must use its own chemical prior, producing a broader
//      distribution. Empirical evidence: 10 examples → 20 unique; 45 examples
//      → 3 unique. The trend strongly suggests 0 examples → ≥ 30 unique.
//   B) Increase temperature from T=1.6 to T=1.8. Higher T widens the token
//      distribution at each step, reducing the probability mass on the single
//      most-likely continuation and spreading probability over more molecules.
//   C) Keep ALL other Attempt 9 elements unchanged:
//      - NCO-only check (forces extension for "O=C=N" format = most isocyanates)
//      - minSpanLength=5 (same)
//      - tokenCount<6 penalty phase (same)
//      - CloseSpanWithinBudget fallback (same)
//   Rationale for not changing more: Attempts 35-36 both broke the NCO mechanism
//   and regressed; Attempt 37 broke guidance → regression. Minimal diff from
//   the proven winner.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   - OpenConstrainedSpan: sets currentConstrainedOut := []; parser.IsValidPrefix([])
//     holds by precondition. ✓
//   - IsCompletePrefix + hasNCO>0 → CloseConstrainedSpan: sets insideConstrainedOut
//     := false; implication vacuous; currentConstrainedOut := []. ✓
//   - IsCompletePrefix + hasNCO==0 → SafeTemperatureConstrainedStep: hard-masks to
//     parser-valid tokens plus EOS; AppendConstrainedToken postcondition yields
//     parser.IsValidPrefix(new currentConstrainedOut). ✓
//   - else (not-yet-complete) → SafePenalizedConstrainedStep / SafeTemperature /
//     GroupBoostedConstrainedStep: all hard-mask to parser-valid tokens plus EOS;
//     AppendConstrainedToken preserves validity. ✓
//   - EOS + close sub-branch → CloseConstrainedSpan: sets insideConstrainedOut
//     := false. ✓
//   - EOS without close: state unchanged; invariant preserved by induction. ✓
//   - Post-loop CloseSpanWithinBudget: postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   - OpenConstrainedSpan: |generated| += 1 ("<<"), steps += 1. ✓
//   - hasNCO>0 → CloseConstrainedSpan: |generated| += 1 (">>"), steps += 1;
//     guard ensures steps <= maxSteps. ✓
//   - hasNCO==0 → SafeTemperatureConstrainedStep: steps += 1; AppendConstrainedToken
//     adds ≤ 1 visible token; EOS adds 0. ✓
//   - else penalty/temp/group step: steps += 1; AppendConstrainedToken adds ≤ 1
//     visible token; EOS adds 0. ✓
//   - EOS → close sub-branch: prior step already incremented steps; inner guard
//     steps < maxSteps ensures close step keeps steps ≤ maxSteps; |generated|
//     += 1 from close. ✓
//   - Post-loop: closeBudget = maxSteps - steps; CloseSpanWithinBudget postcondition:
//     |cg| ≤ |generated| + closeBudget ≤ |generatedPrefix| + maxSteps;
//     steps := maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one valid, unique SMILES string for a novel isocyanate molecule. The isocyanate functional group is N=C=O (as in R-N=C=O). Be creative and generate a structurally unique molecule. Output ONLY the SMILES string with no other text.");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

var minSpanLength: nat := 5;
var tokenCount: nat := 0;
var commonTokens: seq<Token> := ["C", "CC", "O"];

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
    if hasNCO > 0 {
      if steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      } else {
        break;
      }
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.8, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        tokenCount := tokenCount + 1;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;

    if tokenCount < 6 {
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, commonTokens, 4.0, eosToken
      );
    } else if tokenCount < 20 {
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.8, eosToken
      );
    } else {
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
        var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
        if hasNCO > 0 {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  }
}

if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

